for name in dir(svc):
    obj = getattr(svc, name)
    if inspect.ismodule(obj):
        if hasattr(obj, '__all__'):
            if any('sync' in x.lower() or 'lakebase' in x.lower() for x in obj.__all__):
                print('Module:', name, [x for x in obj.__all__ if 'sync' in x.lower() or 'lakebase' in x.lower()])
